Q_WHAT = ["What is {t}?", "Can you explain {t}?", "Explain {t} to me.", "Tell me about {t}.", "I keep hearing about {t}. What is it?", "what's {t} and how does it work?"]
Q_EX = ["Give me an example of {t}.", "Can you give a real-world example involving {t}?", "What's a concrete example that illustrates {t}?"]
Q_MIS = ["What's a common misunderstanding about {t}?", "Is there anything people often get wrong about {t}?", "What should I be careful about with {t}?"]
Q_BRIEF = ["In one sentence, what is {t}?", "Quick definition of {t}?", "Briefly, {t}: what is it?"]
SYS = SYS_GENERAL


def lc(s):
    return s[0].lower() + s[1:] if s and not s[:2].isupper() else s


for area, topic, d, m, e, c in T:
    tt = topic
    out.append(mk(CAT, "knowledge_" + area, [("user", R.choice(Q_WHAT).format(t=tt)), ("assistant", f"{d} {m}")], "k_" + topic, "easy", "authored", pick(R, SYS)))
    out.append(mk(CAT, "knowledge_" + area, [("user", R.choice(Q_EX).format(t=tt)), ("assistant", f"{e} {m.split('. ')[0].rstrip('.')}.")], "k_" + topic, "easy", "authored", pick(R, SYS)))
    out.append(mk(CAT, "knowledge_" + area, [("user", R.choice(Q_MIS).format(t=tt)), ("assistant", c)], "k_" + topic, "medium", "authored", pick(R, SYS)))
    out.append(mk(CAT, "knowledge_" + area, [("user", R.choice(Q_BRIEF).format(t=tt)), ("assistant", d)], "k_" + topic, "easy", "authored", pick(R, SYS)))

print("topics:", len(T))
save("knowledge", out)
